17 module tcdm_arbiter_2x1
18 (
19     input logic                   clk_i,
20     input logic                   rst_ni,
21 
22     XBAR_TCDM_BUS.Slave           tcdm_bus_1_i,
23     XBAR_TCDM_BUS.Slave           tcdm_bus_0_i,
24     XBAR_TCDM_BUS.Master          tcdm_bus_o
25 );
26 
27    logic SEL_req;
28    logic SEL_resp;
29    logic RR_FLAG;
30 
31    enum logic[2:0] {IDLE, WAIT_GNT_0, WAIT_GNT_1, WAIT_VALID_0, WAIT_VALID_1 } offset_fsm_cs, offset_fsm_ns;
32 
33     // offset FSM state transition logic
34     always_comb
35     begin
36       offset_fsm_ns        = offset_fsm_cs;
37       tcdm_bus_o.req       = 1'b0;
38       tcdm_bus_0_i.gnt     = 1'b0;
39       tcdm_bus_1_i.gnt     = 1'b0;
40       tcdm_bus_0_i.r_valid = 1'b0;
41       tcdm_bus_1_i.r_valid = 1'b0;
42       tcdm_bus_0_i.r_opc   = 1'b0;
43       tcdm_bus_1_i.r_opc   = 1'b0;
44       tcdm_bus_0_i.r_rdata = tcdm_bus_o.r_rdata;
45       tcdm_bus_1_i.r_rdata = tcdm_bus_o.r_rdata;
46       tcdm_bus_o.add       = tcdm_bus_0_i.add;
47       tcdm_bus_o.wen       = tcdm_bus_0_i.wen;
48       tcdm_bus_o.wdata     = tcdm_bus_0_i.wdata;
49       tcdm_bus_o.be        = tcdm_bus_0_i.be;
50 
51       unique case (offset_fsm_cs)
52 
53         IDLE: begin
54 
55           if (tcdm_bus_0_i.req) begin
56             tcdm_bus_o.req     = tcdm_bus_0_i.req;
57             tcdm_bus_0_i.gnt   = tcdm_bus_o.gnt;
58             tcdm_bus_0_i.r_opc = tcdm_bus_o.r_opc;
59             tcdm_bus_o.add     = tcdm_bus_0_i.add;
60             tcdm_bus_o.wen     = tcdm_bus_0_i.wen;
61             tcdm_bus_o.wdata   = tcdm_bus_0_i.wdata;
62             tcdm_bus_o.be      = tcdm_bus_0_i.be;
63 
64             offset_fsm_ns      = tcdm_bus_o.gnt ? WAIT_VALID_0 : WAIT_GNT_0;
65           end else if(tcdm_bus_1_i.req) begin
66             tcdm_bus_o.req     = tcdm_bus_1_i.req;
67             tcdm_bus_1_i.gnt   = tcdm_bus_o.gnt;
68             tcdm_bus_1_i.r_opc = tcdm_bus_o.r_opc;
69             tcdm_bus_o.add     = tcdm_bus_1_i.add;
70             tcdm_bus_o.wen     = tcdm_bus_1_i.wen;
71             tcdm_bus_o.wdata   = tcdm_bus_1_i.wdata;
72             tcdm_bus_o.be      = tcdm_bus_1_i.be;
73 
74             offset_fsm_ns      = tcdm_bus_o.gnt ? WAIT_VALID_1 : WAIT_GNT_1;
75           end
76         end
77 
78         WAIT_GNT_0: begin
79           tcdm_bus_o.req       = tcdm_bus_0_i.req;
80           tcdm_bus_0_i.gnt     = tcdm_bus_o.gnt;
81           tcdm_bus_0_i.r_opc   = tcdm_bus_o.r_opc;
82           tcdm_bus_0_i.r_valid = tcdm_bus_o.r_valid;
83           tcdm_bus_o.add       = tcdm_bus_0_i.add;
84           tcdm_bus_o.wen       = tcdm_bus_0_i.wen;
85           tcdm_bus_o.wdata     = tcdm_bus_0_i.wdata;
86           tcdm_bus_o.be        = tcdm_bus_0_i.be;
87           offset_fsm_ns        = tcdm_bus_o.gnt ? WAIT_VALID_0 : WAIT_GNT_0;
88         end
89 
90         WAIT_VALID_0: begin
91           tcdm_bus_o.req       = tcdm_bus_0_i.req;
92           tcdm_bus_0_i.gnt     = tcdm_bus_o.gnt;
93           tcdm_bus_0_i.r_opc   = tcdm_bus_o.r_opc;
94           tcdm_bus_0_i.r_valid = tcdm_bus_o.r_valid;
95           tcdm_bus_o.add       = tcdm_bus_0_i.add;
96           tcdm_bus_o.wen       = tcdm_bus_0_i.wen;
97           tcdm_bus_o.wdata     = tcdm_bus_0_i.wdata;
98           tcdm_bus_o.be        = tcdm_bus_0_i.be;
99           offset_fsm_ns        = tcdm_bus_o.r_valid ? IDLE : WAIT_VALID_0;
100         end
101 
102         WAIT_GNT_1: begin
103           tcdm_bus_o.req       = tcdm_bus_1_i.req;
104           tcdm_bus_1_i.gnt     = tcdm_bus_o.gnt;
105           tcdm_bus_1_i.r_opc   = tcdm_bus_o.r_opc;
106           tcdm_bus_1_i.r_valid = tcdm_bus_o.r_valid;
107           tcdm_bus_o.add       = tcdm_bus_1_i.add;
108           tcdm_bus_o.wen       = tcdm_bus_1_i.wen;
109           tcdm_bus_o.wdata     = tcdm_bus_1_i.wdata;
110           tcdm_bus_o.be        = tcdm_bus_1_i.be;
111           offset_fsm_ns        = tcdm_bus_o.gnt ? WAIT_VALID_1 : WAIT_GNT_1;
112         end
113 
114         WAIT_VALID_1: begin
115           tcdm_bus_o.req       = tcdm_bus_1_i.req;
116           tcdm_bus_1_i.gnt     = tcdm_bus_o.gnt;
117           tcdm_bus_1_i.r_opc   = tcdm_bus_o.r_opc;
118           tcdm_bus_1_i.r_valid = tcdm_bus_o.r_valid;
119           tcdm_bus_o.add       = tcdm_bus_1_i.add;
120           tcdm_bus_o.wen       = tcdm_bus_1_i.wen;
121           tcdm_bus_o.wdata     = tcdm_bus_1_i.wdata;
122           tcdm_bus_o.be        = tcdm_bus_1_i.be;
123           offset_fsm_ns        = tcdm_bus_o.r_valid ? IDLE : WAIT_VALID_1;
124         end // case: WAIT_VALID_1
125 
126         default: begin
127           offset_fsm_ns = IDLE;
128         end
129 
130       endcase
131     end
132 
133 
134      always_ff @(posedge clk_i or negedge rst_ni)
135      begin : RR_SEL_resp_GEN
136         if(~rst_ni)
137         begin
138            offset_fsm_cs <= IDLE;
139         end
140         else
141         begin
142            offset_fsm_cs <= offset_fsm_ns;
143         end
144      end
